'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const arrow='<svg aria-hidden="true"><use href="#arrow"/></svg>';
const dialog=$('#detail');let trigger;
function openDetail(html,source){trigger=source;$('#dialog-content').innerHTML=html;dialog.showModal();$('#close-dialog').focus();}
function closeDetail(){dialog.querySelectorAll('video').forEach(v=>v.pause());dialog.close();trigger?.focus();}
$('#close-dialog').addEventListener('click',closeDetail);
dialog.addEventListener('cancel',e=>{e.preventDefault();closeDetail();});
dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeDetail();}});
const demos=[
 '<div class="bubble user"><small>SEU PEDIDO</small>Quero apresentar este imóvel no feed. Use as fotos que enviei e mantenha uma linha elegante, com pouco texto.</div><div class="bubble"><small>HELPU</small>Vamos usar sua referência visual como ponto de partida. A prévia ficará disponível para você revisar antes de aprovar.</div>',
 '<div class="bubble"><small>PRÉVIA PARA REVISÃO · EXEMPLO</small><img class="demo-image" src="/apresentacao-publica/assets/imobiliaria.jpg" alt="Exemplo de composição imobiliária">Uma direção editorial, com a fotografia em destaque e uma chamada curta.</div><div class="demo-approval">Você confere o material e a legenda.</div>',
 '<div class="bubble user"><small>SEU AJUSTE</small>Quero dar mais destaque à foto e deixar a chamada ainda mais curta.</div><div class="bubble"><small>HELPU</small>Esse é o momento de refinar a hierarquia, o texto e a composição. A versão revisada volta para sua aprovação.</div><div class="demo-approval">Uma rodada de ajustes incluída por entrega.</div>',
 '<div class="bubble"><small>DEPOIS DA SUA APROVAÇÃO</small>O arquivo final e a legenda ficam disponíveis na biblioteca. A entrega aprovada passa a contar no seu plano.</div><div class="bubble user">E a publicação?</div><div class="bubble">No Essencial, você publica. No Assistido, a equipe publica no perfil combinado, após aprovarmos versão, legenda e data.</div>'
];
function showStep(index,focus=false){$$('[data-step]').forEach((b,i)=>{b.setAttribute('aria-selected',String(i===index));b.tabIndex=i===index?0:-1;if(focus&&i===index)b.focus();});$('#demo-panel').setAttribute('aria-labelledby','step-'+index);$('#demo-body').innerHTML=demos[index];}
$$('[data-step]').forEach(b=>{b.addEventListener('click',()=>showStep(+b.dataset.step));b.addEventListener('keydown',e=>{const i=+b.dataset.step;let n;if(['ArrowRight','ArrowDown'].includes(e.key))n=(i+1)%4;else if(['ArrowLeft','ArrowUp'].includes(e.key))n=(i+3)%4;else if(e.key==='Home')n=0;else if(e.key==='End')n=3;else return;e.preventDefault();showStep(n,true);});});showStep(0);
$('#show-portal').addEventListener('click',e=>openDetail('<p class="eyebrow">POR DENTRO DO PRODUTO</p><h2>Seu espaço de criação.</h2><p>Captura do portal em ambiente de demonstração: conversa, programação e acesso à biblioteca em uma mesma experiência.</p><img src="/apresentacao-publica/assets/portal.png" alt="Tela do portal Helpu com chat, programação e acesso ao WhatsApp">',e.currentTarget));
$$('[data-art]').forEach(b=>b.addEventListener('click',()=>openDetail('<p class="eyebrow">EXEMPLO DA BIBLIOTECA HELPU</p><h2>'+ (b.dataset.art==='imobiliaria'?'Uma direção editorial.':'Produto com presença.')+'</h2><p>Modelo conceitual. A criação para sua empresa usa sua marca, seus materiais e suas referências.</p><img src="/apresentacao-publica/assets/'+b.dataset.art+'.jpg" alt="Modelo de criativo ampliado">',b)));
const questions=[
 {title:'Em qual setor sua empresa atua?',options:['Imobiliário','Bebidas e alimentação','Comércio e varejo','Serviços e profissionais','Outro setor']},
 {title:'Quem cuida do marketing hoje?',options:['Eu mesmo ou minha equipe','Uma agência ou profissional','Ainda não temos uma rotina']},
 {title:'O que mais dificulta sua rotina?',options:['Falta de tempo para criar','Falta de constância','Visual sem uma identidade','Pedidos e arquivos desorganizados','Pouca procura por clientes']},
 {title:'O que você quer melhorar primeiro?',options:['Criar e organizar meus conteúdos','Ter ajuda para publicar','Entender minha marca e estratégia']},
 {title:'Quanto investe em produção e gestão por mês?',hint:'Não inclua a verba de anúncios. Essa resposta é opcional.',options:['Ainda não invisto','Até R$ 700','De R$ 701 a R$ 1.500','Acima de R$ 1.500','Prefiro não informar']}
];
let step=0,answers=Array(5).fill(''),recommended='';
function drawQuestion(){const q=questions[step];$('#quiz-content').innerHTML='<h3 id="question-title">'+q.title+'</h3>'+(q.hint?'<p class="small-note">'+q.hint+'</p>':'')+'<div class="choices" role="group" aria-labelledby="question-title">'+q.options.map((x,i)=>'<label class="choice"><input type="radio" name="answer" value="'+i+'" '+(answers[step]===x?'checked':'')+'><span>'+x+'</span></label>').join('')+'</div>';$('#quiz-progress').textContent='0'+(step+1)+' / 05';$('#progress-fill').style.width=(step+1)*20+'%';$('#quiz-back').hidden=step===0;$('#quiz-next').innerHTML=(step===4?'Ver minha direção':'Continuar')+' '+arrow;$('#quiz-error').hidden=true;}
$('#quiz-content').addEventListener('change',e=>{if(e.target.name==='answer'){answers[step]=questions[step].options[+e.target.value];$('#quiz-error').hidden=true;}});
$('#quiz-back').addEventListener('click',()=>{if(step>0){step--;drawQuestion();}});
$('#quiz-form').addEventListener('submit',e=>{e.preventDefault();if(!answers[step]){if(step===4)answers[step]='Prefiro não informar';else{$('#quiz-error').hidden=false;return;}}if(step<4){step++;drawQuestion();}else showResult();});
function showResult(){const strategy=answers[3]==='Entender minha marca e estratégia',assisted=answers[3]==='Ter ajuda para publicar';recommended=strategy?'Diagnóstico e Estratégia — R$ 1.790, pagamento único':assisted?'Helpu Assistido — R$ 990/mês':'Helpu Essencial — R$ 690/mês';const emphasis={ 'Falta de tempo para criar':'Concentrar os pedidos e começar com os materiais que você já tem.', 'Falta de constância':'Organizar temas e datas para construir uma rotina de conteúdo.', 'Visual sem uma identidade':'Reunir marca e referências antes de iniciar a criação.', 'Pedidos e arquivos desorganizados':'Centralizar referências, prévias e versões aprovadas.', 'Pouca procura por clientes':'Revisar mensagem, oferta e caminho de contato; conteúdo sozinho não garante vendas.'};$('#quiz-form').hidden=true;$('#quiz-progress').textContent='SEU RESULTADO';$('#quiz-result').hidden=false;$('#quiz-result').innerHTML='<p class="result-tag">UMA DIREÇÃO PARA COMEÇAR</p><h3>'+recommended+'</h3><p>'+ (strategy?'Você sinalizou que precisa de direção antes de ampliar a produção. A consultoria avulsa é o ponto de partida sugerido.':assisted?'Você quer apoio também na publicação. O Assistido combina criação com revisão e publicação pela equipe.':'Você quer criar e organizar conteúdos. O Essencial permite acompanhar as entregas e publicar com autonomia.')+'</p><ul><li>Seu setor: '+answers[0]+'.</li><li>'+emphasis[answers[2]]+'</li><li>Investimento informado: '+answers[4]+'.</li></ul><p class="small-note">Indicação baseada nas suas respostas, sem análise externa do negócio ou garantia de resultado. O valor informado não foi usado para prometer economia.</p><button class="button dark" id="result-proposal">Ver meu próximo passo '+arrow+'</button><button class="quiet-link" id="restart">Refazer minhas respostas</button>';$('#result-proposal').addEventListener('click',e=>proposal(recommended,e.currentTarget));$('#restart').addEventListener('click',()=>{step=0;$('#quiz-form').hidden=false;$('#quiz-result').hidden=true;drawQuestion();});}
drawQuestion();
function proposal(offer,source){const summary=['Olá, equipe Helpu!','Tenho interesse em: '+offer,...(answers.every(Boolean)?['','Meu contexto:',...questions.map((q,i)=>q.title+' '+answers[i])]:[]),'','Quero conhecer o escopo, as condições de pagamento e a data de início.'].join('\n');openDetail('<p class="eyebrow">SEU PRÓXIMO PASSO</p><h2>Uma proposta que começa pelo seu momento.</h2><p>Confira seu resumo e abra o WhatsApp para conversar com a equipe Helpu. Nenhuma mensagem ou cobrança é enviada automaticamente.</p><label for="proposal-text" class="eyebrow">MENSAGEM PARA A EQUIPE</label><textarea id="proposal-text" readonly></textarea><div class="modal-actions"><a class="button orange" id="contact-proposal" target="_blank" rel="noopener">Conversar no WhatsApp</a><button class="button outline" id="copy-proposal">Copiar mensagem '+arrow+'</button><button class="button outline" id="download-proposal">Baixar resumo</button></div><p id="copy-status" role="status"></p>',source);$('#proposal-text').value=summary;$('#contact-proposal').href='https://wa.me/555481316829?text='+encodeURIComponent(summary);$('#copy-proposal').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(summary);$('#copy-status').textContent='Mensagem copiada.';}catch{$('#proposal-text').focus();$('#proposal-text').select();$('#copy-status').textContent='Selecione “Copiar” no seu dispositivo para copiar o texto destacado.';}});$('#download-proposal').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([summary],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='meu-proximo-passo-helpu.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
$$('[data-proposal]').forEach(b=>b.addEventListener('click',()=>proposal(b.dataset.proposal,b)));
const comparisonOffers={a:{price:849,scope:'2 carrosséis, edição de cerca de 8 vídeos, capas e stories informativos. Planejamento e reuniões. O cliente publica.',support:'Segunda a sábado, pelo WhatsApp.',adjust:'Alterações em materiais não aprovados, sem custo extra, conforme a proposta.'},b:{price:2600,scope:'8 posts: 2 cards ou carrosséis + 6 Reels. Planejamento, organização do perfil e pacote com captação mensal, reuniões e publicação.',support:'Grupo de WhatsApp e reunião mensal. Horário não informado.',adjust:'Quantidade de rodadas não informada no material enviado.'},c:{price:3400,scope:'12 posts: 4 cards ou carrosséis + 8 Reels. Planejamento, organização do perfil e pacote com captação mensal, reuniões e publicação.',support:'Grupo de WhatsApp e reunião mensal. Horário não informado.',adjust:'Quantidade de rodadas não informada no material enviado.'}};
const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});
function compare(){const reference=comparisonOffers[$('#compare-reference').value],assisted=$('#compare-helpu').value==='assisted',price=assisted?990:690,difference=reference.price-price;$('#compare-price-a').textContent=money(reference.price);$('#compare-price-h').textContent=money(price);$('#compare-scope').textContent=reference.scope;$('#compare-support').textContent=reference.support;$('#compare-adjust').textContent=reference.adjust;$('#compare-publish').textContent=assisted?'A equipe revisa e publica em um perfil.':'Você aprova, baixa e publica.';$('#compare-delta').textContent=money(Math.abs(difference))+(difference>=0?' a menos':' a mais')+'/mês';$('#compare-delta-note').textContent='Diferença nominal de '+(Math.abs(difference)/reference.price*100).toLocaleString('pt-BR',{maximumFractionDigits:1})+'% em relação ao pacote selecionado. Os serviços e volumes são diferentes; isso não representa economia para um escopo equivalente.';}
$('#compare-reference').addEventListener('change',compare);$('#compare-helpu').addEventListener('change',compare);compare();
const chapters=[
 {mark:'2020',place:'VACARIA · O COMEÇO',title:'Antes de automatizar,<br>a gente aprendeu a fazer.',text:'Conteúdo por conteúdo. Cliente por cliente. A primeira Helpu nasceu em 2020, quando essas ferramentas de IA ainda não faziam parte da rotina de criação.',caption:'Uma história construída com trabalho.'},
 {mark:'SP',place:'SÃO PAULO · UM ANO DE DESAFIOS',title:'Para crescer,<br>foi preciso partir.',text:'Encerramos a operação em Vacaria e saímos da zona de conforto. Em São Paulo, o trabalho com franquias, inaugurações, tecnologia e equipamentos ampliou nossa forma de enxergar os negócios.',caption:'Um novo lugar. Uma nova perspectiva.'},
 {mark:'CE',place:'FORTALEZA · DOIS ANOS DE TRANSFORMAÇÃO',title:'A vida também<br>ensina a construir.',text:'Em Fortaleza, crescemos por dentro e por fora. Foram dois anos de desenvolvimento profissional e pessoal. Nossa filha nasceu. Mudaram as prioridades e a forma de pensar o futuro.',caption:'O trabalho ganhou novos motivos.'},
 {mark:'RS',place:'PORTO ALEGRE · UM ANO DE PREPARAÇÃO',title:'Aprender virou<br>parte do caminho.',text:'De volta ao Sul, seguimos trabalhando e estudando. Eventos, feiras, reuniões e consultorias aproximaram experiência, tecnologia e uma ideia que começava a ganhar forma.',caption:'Experiência amadurece quando vira direção.'},
 {mark:'VOLTA',place:'VACARIA · O REENCONTRO',title:'Voltamos ao começo.<br>Com outro olhar.',text:'Retornamos para trazer esse conhecimento ao mercado local. Não para repetir uma fórmula, mas para construir um caminho que faça sentido para a realidade de quem empreende aqui.',caption:'As raízes ficaram. A visão cresceu.'},
 {mark:'HOJE',place:'HELPU · O NOVO CAPÍTULO',title:'Mais tecnologia.<br>O mesmo compromisso.',text:'A nova Helpu conecta essa bagagem a uma forma mais simples de criar, organizar e aprovar conteúdo. Nossa missão é transformar investimento em trabalho com direção, agilidade e foco em resultado.',caption:'Seu marketing começa aqui.'}
];
let chapter=0;
function showChapter(index,focus=false){chapter=index;const c=chapters[index];$('#story-year').textContent=c.mark;$('#story-place').textContent=c.place;$('#story-title').innerHTML=c.title;$('#story-copy').textContent=c.text;$('#story-caption').textContent=c.caption;$('#story-count').textContent='0'+(index+1)+' / 06';$('#story-panel').setAttribute('aria-labelledby','chapter-'+index);$('#story-prev').disabled=index===0;$('#story-next').disabled=index===chapters.length-1;$$('[data-chapter]').forEach((b,i)=>{b.setAttribute('aria-selected',String(i===index));b.tabIndex=i===index?0:-1;if(focus&&i===index)b.focus();});updateStoryMedia(index);}
$$('[data-chapter]').forEach(b=>{b.addEventListener('click',()=>showChapter(+b.dataset.chapter));b.addEventListener('keydown',e=>{let i=+b.dataset.chapter;if(e.key==='ArrowRight')i=(i+1)%6;else if(e.key==='ArrowLeft')i=(i+5)%6;else if(e.key==='Home')i=0;else if(e.key==='End')i=5;else return;e.preventDefault();showChapter(i,true);});});
$('#story-prev').addEventListener('click',()=>{if(chapter>0)showChapter(chapter-1);});$('#story-next').addEventListener('click',()=>{if(chapter<5)showChapter(chapter+1);});
$('#read-story').addEventListener('click',e=>openDetail('<p class="eyebrow">DESDE 2020</p><h2>Antes da tecnologia,<br>veio a estrada.</h2><p>A Helpu começou em Vacaria, em 2020. Antes de essas ferramentas de inteligência artificial fazerem parte do cotidiano, nosso trabalho já era criar, produzir e estar perto das empresas. Foram mais de 15 mil conteúdos, mais de 78 empresas atendidas e um alcance de mais de 15 milhões de pessoas, segundo o histórico relatado pelos fundadores.</p><p>Participamos da construção e do posicionamento de negócios de setores como hotelaria, alimentação e mercado imobiliário. E, depois de tanto fazer, escolhemos aprender de outro jeito: encerramos a operação local e partimos.</p><p>São Paulo nos tirou da zona de conforto. Durante um ano, trabalhamos com franquias, inaugurações, tecnologia e equipamentos. Aprendemos a olhar mais de perto para o consumidor, a operação e o que move um negócio.</p><p>Em Fortaleza, foram mais dois anos. Crescemos profissionalmente, amadurecemos como pessoas e tivemos nossa filha. A vida trouxe um novo sentido para construir algo que valesse a pena.</p><p>Porto Alegre marcou nossa volta ao Sul. Mais um ano de trabalho, estudo, eventos, feiras, reuniões e consultorias. A experiência começou a se transformar em uma nova direção.</p><p>Até que voltamos a Vacaria. Com as mesmas raízes e uma visão diferente. Voltamos para aproximar o que aprendemos da realidade de quem empreende aqui.</p><p>A nova Helpu nasce desse encontro: experiência de verdade e tecnologia a serviço da criação. Para dar mais agilidade, organizar a rotina e fazer cada investimento ter uma intenção clara. Resultado é o compromisso que orienta nosso trabalho — nunca uma promessa automática.</p><p><strong>A tecnologia é nova. A experiência vem de longe.<br>E o próximo capítulo pode ser com a sua empresa.</strong></p>',e.currentTarget));
function localMediaPath(value){if(typeof value!=='string'||!value.trim())return '';const v=value.trim();if(/^[a-z]+:/i.test(v)||v.startsWith('/')||v.startsWith('\\')||v.split(/[\\/]/).includes('..'))return '';return v;}
function updateStoryMedia(index){const media=window.HELPU_STORY_MEDIA?.chapters?.[index],path=localMediaPath(media?.image),holder=$('.story-visual');holder.querySelector('img')?.remove();holder.classList.remove('has-photo');holder.setAttribute('aria-hidden','true');if(!path)return;const image=new Image();image.alt=media.alt||'Registro real da trajetória da Helpu';image.onload=()=>{if(chapter!==index)return;holder.classList.add('has-photo');holder.removeAttribute('aria-hidden');};image.onerror=()=>{if(chapter===index){image.remove();holder.classList.remove('has-photo');holder.setAttribute('aria-hidden','true');}};image.src=path;holder.prepend(image);}
const film=window.HELPU_STORY_MEDIA?.film,filmPath=localMediaPath(film?.src);
const watch=$('#watch-story');watch.hidden=!filmPath;
watch.addEventListener('click',()=>{if(!filmPath)return;openDetail('<p class="eyebrow">NOSSA HISTÓRIA</p><h2 id="film-title"></h2><div id="story-player"></div><p class="small-note">Ative o som para acompanhar a história. Você pode pausar ou fechar quando quiser.</p>',watch);$('#film-title').textContent=film.title||'A experiência vem de longe';const video=document.createElement('video');video.controls=true;video.playsInline=true;video.preload='metadata';video.src=filmPath;video.poster=localMediaPath(film.poster);video.setAttribute('aria-label',film.title||'A história da Helpu');const captions=localMediaPath(film.captions);if(captions){const track=document.createElement('track');track.kind='captions';track.srclang='pt-BR';track.label='Português';track.src=captions;video.append(track);}video.addEventListener('error',()=>{const p=document.createElement('p');p.setAttribute('role','status');p.textContent='O filme não carregou. Você pode conhecer a trajetória pelos capítulos da apresentação.';$('#story-player').replaceChildren(p);});$('#story-player').append(video);});
updateStoryMedia(0);
